function setEmpScDates(t,v,iin){let eD=new Date(),sD=new Date();if(t==='single'){if(v){let p=v.split('-');sD=new Date(p[0],p[1]-1,p[2]);eD=new Date(p[0],p[1]-1,p[2])}}else if(t==='month'){if(v){let p=v.split('-');sD=new Date(p[0],p[1]-1,1);eD=new Date(p[0],p[1],0)}}document.getElementById('emp-sc-start').value=formatDateLocal(sD);document.getElementById('emp-sc-end').value=formatDateLocal(eD);renderEmpScDetailsData(iin)}
function renderEmpScDetailsData(iin){let e=allEmployeesData.find(emp=>safeIin(emp.iin)===safeIin(iin));if(!e)return;let sD=document.getElementById("emp-sc-start").value,eD=document.getElementById("emp-sc-end").value,sT=new Date(sD).getTime(),eT=new Date(eD).getTime()+86400000,s=e.ptsHistory.filter(p=>{if(p.type!=="Начисление")return!1;let str=String(p.source).toLowerCase();if(!(str.includes("сц")||str.includes("фокус")||str.includes("trade-in")))return!1;let rd=parseCustomDate(p.date);return rd>=sT&&rd<=eT});let lH="<div class='card' style='padding:0; overflow:hidden;'>";if(s.length>0){lH+=groupAndRenderByMonth(s,i=>{let rD=i.reason||"",m=rD.match(/\n\[(.*?)\]$/);if(m)rD=rD.replace(/\n\[(.*?)\]$/,"").trim();return buildStandardRow({title:rD,typeText:i.source,typeColor:getSourceColor(i.source),dateText:i.date,nameText:e.name,hasBorder:!1})})}else{lH+="<div style='padding:15px;text-align:center;color:gray;font-size:13px;'>В выбранном периоде пусто</div>"}lH+="</div>";document.getElementById("emp-sc-render-area").innerHTML=lH}
